let loggingEnabled = false;
export function enableLogging() {
    loggingEnabled = true;
}
export function DEV(strings, ...args) {
    if (!loggingEnabled)
        return;
    const rejoined = [`ENGINE ${strings[0]}`];
    for (let i = 0; i < args.length; i++) {
        rejoined.push(args[i], strings[i + 1]);
    }
    console.log(...rejoined);
}
